"use client";

// ── The homepage as a film (per the 10/13 client meeting) ──
// No page scrolling. One fixed frame; scenes play like a movie with a
// YouTube-style transport bar up top (pause, drag-scrub anywhere, chapter
// hover). Every scene's text is server-rendered in the DOM (opacity does the
// showing/hiding), so SEO/AEO indexing sees the whole story.
//
// TIMING MODEL — the narration drives everything:
//   • Each on-screen line has its own narration clip, read verbatim
//     (public/audio/film/<id>.mp3, generated by
//     scripts/generate-film-narration.ts, which also writes the exact clip
//     lengths to narration-timings.ts).
//   • PLAN below lays each scene's clips out in time (lead-in, gaps, tail).
//     Scene durations and every text-arrival delay are DERIVED from that, so
//     words appear as the voice says them. Change the copy → re-run the
//     script → timing follows automatically.
//   • All CSS animations run off the film clock: pausing freezes them, and
//     seeking remounts the active scene with negative delays so the frame
//     shows exactly what belongs at that moment (client 10/14: "the text
//     needs to be able to stop, move back, etc based on the scroll up top").
//   • While narration is loading/buffering the clock and animations hold, so
//     voice and text can't drift apart.
//
// Branding: the old site's system (Open Sans 800, cream / charcoal / sky).

import Link from "next/link";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { Play, Pause, Volume2, VolumeX, RotateCcw, Share2 } from "lucide-react";
import { NARR } from "./narration-timings";
import { NewFooter } from "./SiteChrome";

// ── Timeline plan ──
// lead = seconds before the first line; gap = seconds between lines (or a
// per-line [id, gapBefore]); tail = seconds held after the last line.

type Plan = {
  lead: number;
  segs: Array<string | [string, number]>;
  gap?: number;
  tail: number;
};

const PLAN: Record<string, Plan> = {
  cold1: { lead: 2.0, segs: ["cold1"], tail: 1.3 },
  cold2: { lead: 0.9, segs: ["cold2"], tail: 1.3 },
  hero: { lead: 0.8, segs: ["hero1", ["hero2", 0.9]], tail: 1.8 },
  wildfree: { lead: 0.6, segs: ["wild", ["alone", 1.0]], tail: 2.8 },
  familybody: { lead: 1.0, segs: ["fam1", "fam2", "fam3"], gap: 1.4, tail: 2.0 },
  savingtitle: { lead: 0.5, segs: ["save1", ["save2", 0.3]], tail: 1.3 },
  promisebody: {
    lead: 1.0,
    segs: ["prom1", ["prom2", 1.4], ["pil1", 0.9], ["pil2", 0.5], ["pil3", 0.5]],
    tail: 2.2,
  },
  roamheader: { lead: 0.4, segs: ["roam"], tail: 0.9 },
  graze: { lead: 0.6, segs: ["graze"], tail: 1.6 },
  run: { lead: 0.6, segs: ["run"], tail: 1.6 },
  nap: { lead: 0.6, segs: ["nap"], tail: 1.8 },
  trust: {
    lead: 0.5,
    segs: ["trusthead", ["trust1", 0.9], ["trust2", 1.4], ["trust3", 1.4]],
    tail: 2.0,
  },
  sovereignty: { lead: 0.7, segs: ["sov"], tail: 2.0 },
  storiesheader: { lead: 0.4, segs: ["stories"], tail: 0.9 },
  storiesgrid: { lead: 0.8, segs: ["gabriel", "jackjack", "xander", "brave"], gap: 1.0, tail: 2.4 },
  howstarted: { lead: 1.2, segs: ["started"], tail: 1.8 },
  savemore: { lead: 1.2, segs: ["savemore"], tail: 1.8 },
  visiontitle: { lead: 0.6, segs: ["vtitle"], tail: 1.6 },
  visionpen: { lead: 0.6, segs: ["vpen"], tail: 1.6 },
  visionquiet: { lead: 0.9, segs: ["vquiet"], tail: 2.2 },
  visiondeserve: {
    lead: 0.5,
    segs: ["vdeserve", ["vp1", 0.8], ["vp2", 0.5], ["vp3", 0.5]],
    tail: 2.0,
  },
  visionbuild: { lead: 0.5, segs: ["notsomeday", ["buildit", 0.5]], tail: 3.5 },
  impact: { lead: 0.9, segs: ["impact"], tail: 4.0 },
};

// Narration plays a touch faster than recorded (client 10/13: "just a touch
// faster"); browsers preserve pitch. All timing below is in FILM seconds.
const RATE = 1.12;
/** film-seconds a line takes at playback rate */
const N = (seg: string) => (NARR[seg] ?? 2) / RATE;

const START: Record<string, number> = {}; // seconds into its scene
const DUR: Record<string, number> = {}; // scene durations
const VOICE: Record<string, string[]> = {}; // scene → its clips, in order
for (const [sid, p] of Object.entries(PLAN)) {
  let t = p.lead;
  VOICE[sid] = [];
  p.segs.forEach((entry, i) => {
    const [seg, gapBefore] = typeof entry === "string" ? [entry, p.gap ?? 0.6] : entry;
    if (i > 0) t += gapBefore;
    START[seg] = t;
    VOICE[sid].push(seg);
    t += N(seg);
  });
  DUR[sid] = t + p.tail;
}
/** ms into the scene when a line starts (+ optional offset). */
const at = (seg: string, offMs = 0) => Math.round(START[seg] * 1000) + offMs;
/** ms into the scene when a line ends (+ optional offset). */
const end = (seg: string, offMs = 0) => Math.round((START[seg] + N(seg)) * 1000) + offMs;
/** ms the voice spends on a line — used to pour text in step with it. */
const span = (seg: string) => Math.round(N(seg) * 1000);

interface SceneDef {
  id: string;
  title: string; // scrubber tooltip
  dur: number; // seconds
  render: (active: boolean) => ReactNode;
}

// ── Film clock context ──
// `off` = ms of this scene that had already elapsed when it was (re)mounted
// by a seek. Every animation subtracts it from its delay, so a seek lands
// mid-animation exactly where the film is.
const FilmCtx = createContext(0);
const useOff = () => useContext(FilmCtx);

const EASE = "cubic-bezier(0.2,0.6,0.2,1)";

/** Layered, film-clock-aware CSS animations on one element. */
function Timed({
  active,
  layers,
  className = "",
  style,
  children,
}: {
  active: boolean;
  layers: Array<[name: string, durS: number, delayMs: number, ease?: string]>;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
}) {
  const off = useOff();
  const animation = active
    ? layers.map(([n, d, del, e]) => `${n} ${d}s ${e ?? EASE} ${del - off}ms forwards`).join(", ")
    : "none";
  return (
    <div className={className} style={{ opacity: 0, ...style, animation }}>
      {children}
    </div>
  );
}

function A({
  active,
  anim,
  delay = 0,
  className = "",
  children,
}: {
  active: boolean;
  anim: string;
  delay?: number;
  className?: string;
  children: ReactNode;
}) {
  return (
    <Timed active={active} layers={[[anim, 1.1, delay]]} className={className}>
      {children}
    </Timed>
  );
}

// ── Shared bits ──

const IMG = "/images/film";

function Bleed({
  src,
  darker,
  drift,
  pos = "center",
  children,
}: {
  src: string;
  darker?: boolean;
  /** Slow push-in on the photo while the scene holds (pass `active`). */
  drift?: boolean;
  /** CSS background-position — which part of the photo survives the crop. */
  pos?: string;
  children?: ReactNode;
}) {
  const off = useOff();
  return (
    <div className="absolute inset-0 overflow-hidden">
      <div
        className="absolute inset-0 bg-cover"
        style={{
          backgroundImage: `url(${src})`,
          backgroundPosition: pos,
          animation: drift ? `filmDrift 18s linear ${-off}ms forwards` : "none",
        }}
      />
      <div
        className={`absolute inset-0 ${
          darker
            ? "bg-gradient-to-t from-black/75 via-black/35 to-black/25"
            : "bg-gradient-to-t from-black/65 via-black/20 to-black/10"
        }`}
      />
      {children}
    </div>
  );
}

/** Words pour onto the page in step with the narrator: the line's words are
    spread across ~90% of the time the voice spends on it, so each word lands
    just as it's spoken. */
function Pour({
  text,
  active,
  seg,
  className = "",
  highlights = [],
}: {
  text: string;
  active: boolean;
  /** narration line this text belongs to — sets start time and pace */
  seg: string;
  className?: string;
  /** Phrases that pour in big, bold, and sky — the pillar callouts. */
  highlights?: string[];
}) {
  const off = useOff();
  const words = useMemo(() => text.split(" "), [text]);
  const marked = useMemo(() => {
    const flags = new Array<boolean>(words.length).fill(false);
    const norm = (s: string) => s.toLowerCase().replace(/[^a-z]/g, "");
    for (const phrase of highlights) {
      const pw = phrase.split(" ").map(norm);
      for (let i = 0; i <= words.length - pw.length; i++) {
        if (pw.every((p, j) => norm(words[i + j]) === p)) {
          for (let j = 0; j < pw.length; j++) flags[i + j] = true;
        }
      }
    }
    return flags;
  }, [words, highlights]);
  const startMs = at(seg, -150);
  const wordMs = (span(seg) * 0.9) / Math.max(1, words.length);
  // The space lives OUTSIDE each animated span: inline-block spans swallow
  // their trailing whitespace (jammed words, client screenshot 10/13).
  return (
    <p className={className}>
      {words.map((w, i) => (
        <span key={i}>
          <span
            className={`film-word ${marked[i] ? "font-extrabold text-sky-light text-[1.18em]" : ""}`}
            style={{
              animation: active
                ? `filmWordIn 0.95s cubic-bezier(0.3,0.6,0.25,1) ${Math.round(startMs + i * wordMs - off)}ms forwards`
                : "none",
            }}
          >
            {w}
          </span>{" "}
        </span>
      ))}
    </p>
  );
}

/** Movie title card: zoom-settle + focus pull, then a slow push while held. */
function TitleCard({
  active,
  delay = 0,
  className = "",
  sweep,
  children,
}: {
  active: boolean;
  delay?: number;
  className?: string;
  /** The showpiece: a warm band of light reveals the text left-to-right. */
  sweep?: boolean;
  children: ReactNode;
}) {
  return (
    <Timed active={active} layers={[["filmPush", 11, delay, "linear"]]} style={{ opacity: 1 }}>
      <Timed
        active={active}
        layers={[[sweep ? "filmSweepIn" : "filmTitleIn", sweep ? 2.6 : 1.8, delay, "cubic-bezier(0.25,0.6,0.25,1)"]]}
        className={`${className} ${sweep ? "film-sweep" : ""}`}
      >
        {children}
      </Timed>
    </Timed>
  );
}

/** A timed paragraph beat: fades in at `enter` ms, optionally out at `exit`.
    Paragraphs play ONE AT A TIME in a compact box (client 10/13). */
function Beat({
  active,
  enter,
  exit,
  children,
}: {
  active: boolean;
  enter: number;
  exit?: number;
  children: ReactNode;
}) {
  const layers: Array<[string, number, number, string]> = [["filmParaIn", 0.7, enter, "ease"]];
  if (exit !== undefined) layers.push(["filmParaOut", 0.9, exit, "ease"]);
  return (
    <Timed
      active={active}
      layers={layers}
      className="absolute inset-0 flex items-center justify-center px-6 sm:px-10"
    >
      <div className="w-full">{children}</div>
    </Timed>
  );
}

// ── The scenes ──

const heading = "font-extrabold tracking-tight leading-tight";

function scene(id: string, title: string, render: (a: boolean) => ReactNode): SceneDef {
  return { id, title, dur: DUR[id], render };
}

