const NAV = [
  { label: "Our Story", href: "/our-story" },
  { label: "Their Stories", href: "/donkeys" },
  { label: "Save More Families", href: "/how-to-help" },
  { label: "Make an Impact", href: "/donate" },
];

const UNLOCK = "__unlock";

export default function FilmHome() {
  const scenes = useMemo(buildScenes, []);
  const total = useMemo(
    () => scenes.reduce((s, sc) => s + (Number.isFinite(sc.dur) ? sc.dur : 0), 0),
    [scenes]
  );
  const starts = useMemo(() => {
    let acc = 0;
    return scenes.map((sc) => {
      const v = acc;
      acc += Number.isFinite(sc.dur) ? sc.dur : 0;
      return v;
    });
  }, [scenes]);

  const [idx, setIdx] = useState(0);
  const [fading, setFading] = useState<number | null>(null); // outgoing scene during crossfade
  const [playing, setPlaying] = useState(true);
  const [buffering, setBuffering] = useState(false);
  const [soundOn, setSoundOn] = useState(false);
  const [progress, setProgress] = useState(0); // seconds into the film
  const [hoverTip, setHoverTip] = useState<{ x: number; label: string } | null>(null);
  // per-scene seek state: off = ms already elapsed at (re)mount, k = remount key
  const [seekState, setSeekState] = useState<Record<string, { off: number; k: number }>>({});

  const idxRef = useRef(0);
  const playingRef = useRef(true);
  const soundRef = useRef(false);
  const bufferingRef = useRef(false);
  const bufSinceRef = useRef(0);
  const elapsedRef = useRef(0); // seconds into the current scene
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const preloadRef = useRef<HTMLAudioElement | null>(null);
  const segRef = useRef<string | null>(null);
  idxRef.current = idx;
  playingRef.current = playing;
  soundRef.current = soundOn;

  const setBuf = useCallback((v: boolean) => {
    bufferingRef.current = v;
    if (v) bufSinceRef.current = Date.now();
    setBuffering(v);
  }, []);

  const activeSegAt = useCallback(
    (i: number, t: number): string | null => {
      const v = VOICE[scenes[i]?.id] ?? [];
      return v.find((s) => t >= START[s] - 0.05 && t < START[s] + N(s) - 0.12) ?? null;
    },
    [scenes]
  );

  const preloadAfter = useCallback(
    (seg: string) => {
      // warm the next line (same scene or the next one) so it starts instantly
      const order = scenes.flatMap((s) => VOICE[s.id] ?? []);
      const nxt = order[order.indexOf(seg) + 1];
      if (!nxt) return;
      if (!preloadRef.current) {
        preloadRef.current = new Audio();
        preloadRef.current.preload = "auto";
      }
      preloadRef.current.src = `/audio/film/${nxt}.mp3`;
    },
    [scenes]
  );

  const startSeg = useCallback(
    (seg: string, into: number) => {
      const audio = audioRef.current;
      if (!audio) return;
      segRef.current = seg;
      audio.muted = false;
      audio.src = `/audio/film/${seg}.mp3`;
      audio.defaultPlaybackRate = RATE;
      audio.playbackRate = RATE;
      if (into > 0.2) {
        audio.addEventListener(
          "loadedmetadata",
          () => {
            try {
              audio.currentTime = into * RATE; // film seconds → clip seconds
            } catch {}
          },
          { once: true }
        );
      }
      setBuf(true); // the film holds until the voice actually starts
      void audio.play().catch(() => setBuf(false));
      preloadAfter(seg);
    },
    [preloadAfter, setBuf]
  );

  /** Keep the narration on the line that belongs at the film's current time. */
  const syncAudio = useCallback(() => {
    const audio = audioRef.current;
    if (!audio || segRef.current === UNLOCK) return;
    if (!soundRef.current || !playingRef.current || document.hidden) {
      if (!audio.paused) audio.pause();
      return;
    }
    const t = elapsedRef.current;
    const seg = activeSegAt(idxRef.current, t);
    if (!seg) return; // between lines: let the last one finish naturally
    if (segRef.current !== seg) {
      startSeg(seg, t - START[seg]);
      return;
    }
    if (audio.paused && !audio.ended) {
      void audio.play().catch(() => {});
      return;
    }
    // drift guard (clip seconds = film seconds × RATE)
    if (!audio.paused && audio.readyState >= 3) {
      const want = (t - START[seg]) * RATE;
      if (Math.abs(audio.currentTime - want) > 0.4) audio.currentTime = want;
    }
  }, [activeSegAt, startSeg]);

  /** Jump the film to any point (seconds from the start). */
  const seekTo = useCallback(
    (g: number) => {
      let i = 0;
      if (g >= total) i = scenes.length - 1;
      else while (i < scenes.length - 1 && Number.isFinite(scenes[i].dur) && starts[i + 1] <= g) i++;
      const sceneT = i === scenes.length - 1 ? 0 : Math.max(0, g - starts[i]);
      idxRef.current = i;
      elapsedRef.current = sceneT;
      setIdx(i);
      setFading(null);
      setProgress(starts[i] + sceneT);
      const id = scenes[i].id;
      setSeekState((s) => ({ ...s, [id]: { off: Math.round(sceneT * 1000), k: (s[id]?.k ?? 0) + 1 } }));
      segRef.current = null;
      audioRef.current?.pause();
      setBuf(false);
      syncAudio();
    },
    [scenes, starts, total, setBuf, syncAudio]
  );

  const stepScene = useCallback(
    (dir: 1 | -1) => {
      const i = idxRef.current;
      if (dir < 0 && elapsedRef.current > 1.5) seekTo(starts[i]); // back = restart this scene first
      else seekTo(starts[Math.max(0, Math.min(scenes.length - 1, i + dir))]);
    },
    [scenes.length, starts, seekTo]
  );

  // Master clock. A timer (not rAF, which freezes in occluded windows). It
  // holds while paused, hidden, or waiting on narration to start.
  useEffect(() => {
    let last = Date.now();
    const timer = setInterval(() => {
      const now = Date.now();
      const dt = Math.min(0.5, (now - last) / 1000);
      last = now;
      if (bufferingRef.current && now - bufSinceRef.current > 4000) setBuf(false); // never hang
      if (!playingRef.current || document.hidden || bufferingRef.current) {
        syncAudio();
        return;
      }
      const i = idxRef.current;
      const sc = scenes[i];
      elapsedRef.current += dt;
      if (Number.isFinite(sc.dur) && elapsedRef.current >= sc.dur && i + 1 < scenes.length) {
        const next = i + 1;
        idxRef.current = next;
        elapsedRef.current = 0;
        setFading(i);
        setTimeout(() => setFading((f) => (f === i ? null : f)), 1000);
        setSeekState((s) => ({ ...s, [scenes[next].id]: { off: 0, k: s[scenes[next].id]?.k ?? 0 } }));
        setIdx(next);
      }
      const j = idxRef.current;
      setProgress(starts[j] + Math.min(elapsedRef.current, Number.isFinite(scenes[j].dur) ? scenes[j].dur : 0));
      syncAudio();
    }, 120);
    return () => clearInterval(timer);
  }, [scenes, starts, syncAudio, setBuf]);

  // narration element + buffering signals
  useEffect(() => {
    const audio = new Audio();
    audio.volume = 0.9;
    audio.preload = "auto";
    const onPlaying = () => setBuf(false);
    const onWaiting = () => {
      if (soundRef.current && segRef.current && segRef.current !== UNLOCK) setBuf(true);
    };
    const onError = () => setBuf(false);
    audio.addEventListener("playing", onPlaying);
    audio.addEventListener("waiting", onWaiting);
    audio.addEventListener("error", onError);
    audioRef.current = audio;
    return () => {
      audio.pause();
      audio.removeEventListener("playing", onPlaying);
      audio.removeEventListener("waiting", onWaiting);
      audio.removeEventListener("error", onError);
      audioRef.current = null;
    };
  }, [setBuf]);

  const pauseFilm = useCallback(() => {
    playingRef.current = false;
    setPlaying(false);
    audioRef.current?.pause();
  }, []);
  const resumeFilm = useCallback(() => {
    playingRef.current = true;
    setPlaying(true);
    syncAudio();
  }, [syncAudio]);
  const togglePlay = () => (playingRef.current ? pauseFilm() : resumeFilm());

  // transport inputs: wheel steps scenes, keys, restart event
  useEffect(() => {
    let lastWheel = 0;
    const onWheel = (e: WheelEvent) => {
      // The end screen scrolls like a page (to reach the footer) — the wheel
      // must not jump scenes there.
      if (idxRef.current === scenes.length - 1) return;
      const now = Date.now();
      if (now - lastWheel < 700) return;
      lastWheel = now;
      if (e.deltaY > 10) stepScene(1);
      else if (e.deltaY < -10) stepScene(-1);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === " ") {
        e.preventDefault();
        if (playingRef.current) pauseFilm();
        else resumeFilm();
      } else if (e.key === "ArrowRight") stepScene(1);
      else if (e.key === "ArrowLeft") stepScene(-1);
    };
    const onRestart = () => seekTo(0);
    window.addEventListener("wheel", onWheel, { passive: true });
    window.addEventListener("keydown", onKey);
    window.addEventListener("dd:film-restart", onRestart);
    return () => {
      window.removeEventListener("wheel", onWheel);
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("dd:film-restart", onRestart);
    };
  }, [stepScene, seekTo, pauseFilm, resumeFilm]);

  // press-and-hold on the stage pauses; release resumes
  const holdRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const heldRef = useRef(false);
  const onStageDown = () => {
    holdRef.current = setTimeout(() => {
      heldRef.current = true;
      pauseFilm();
    }, 300);
  };
  const onStageUp = () => {
    if (holdRef.current) clearTimeout(holdRef.current);
    if (heldRef.current) {
      heldRef.current = false;
      resumeFilm();
    }
  };

  const enableSound = () => {
    // runs inside the tap — mobile only allows audio to start in a gesture
    soundRef.current = true;
    setSoundOn(true);
    const audio = audioRef.current;
    if (!audio) return;
    const seg = activeSegAt(idxRef.current, elapsedRef.current);
    if (seg && playingRef.current) {
      startSeg(seg, elapsedRef.current - START[seg]);
      return;
    }
    // Between lines (or paused): unlock the element now so later lines can
    // start on their own (iOS requires the first play() inside a gesture).
    segRef.current = UNLOCK;
    audio.muted = true;
    audio.src = "/audio/film/cold1.mp3";
    audio
      .play()
      .then(() => audio.pause())
      .catch(() => {})
      .finally(() => {
        audio.muted = false;
        if (segRef.current === UNLOCK) segRef.current = null;
      });
  };

  const disableSound = () => {
    soundRef.current = false;
    setSoundOn(false);
    segRef.current = null;
    audioRef.current?.pause();
    setBuf(false);
  };

  // scrubber: click or drag anywhere to seek
  const draggingRef = useRef(false);
  const timeAt = (e: React.PointerEvent<HTMLDivElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    return Math.max(0, Math.min(1, (e.clientX - r.left) / r.width)) * total;
  };
  const titleAt = (g: number) => {
    let i = 0;
    while (i < scenes.length - 1 && Number.isFinite(scenes[i].dur) && starts[i + 1] <= g) i++;
    return scenes[i].title;
  };
  const fmt = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;

  const paused = !playing || buffering;

  return (
    <div className="fixed inset-0 bg-cream text-charcoal overflow-hidden select-none">
      <style>{`
        @keyframes filmFadeUp { from { opacity: 0; transform: translateY(26px); } to { opacity: 1; transform: none; } }
        @keyframes filmComeAt { from { opacity: 0; transform: scale(0.65); } to { opacity: 1; transform: scale(1); } }
        /* "Wild and Free" hands off: dissolves out as "Alone" arrives */
        @keyframes filmHandoff { from { opacity: 1; transform: scale(1); filter: blur(0); } to { opacity: 0; transform: scale(1.06); filter: blur(8px); } }
        /* "Alone Tomorrow": resolves in place, then slowly recedes into the
           distance — left behind (client 10/14) */
        @keyframes filmAlone {
          0% { opacity: 0; transform: scale(1); filter: blur(6px); }
          16% { opacity: 1; transform: scale(1); filter: blur(0); }
          100% { opacity: 0.35; transform: scale(0.74); filter: blur(0.5px); }
        }
        @keyframes filmGrowHold { from { opacity: 0; transform: scale(0.6); } to { opacity: 1; transform: scale(1); } }
        @keyframes filmSlideAcross { from { opacity: 0; transform: translateX(-60vw); } to { opacity: 1; transform: none; } }
        @keyframes filmFromLeft { from { opacity: 0; transform: translateX(-80px); } to { opacity: 1; transform: none; } }
        @keyframes filmFromRight { from { opacity: 0; transform: translateX(80px); } to { opacity: 1; transform: none; } }
        @keyframes filmPushThrough { from { opacity: 1; transform: scale(1); filter: blur(0); } to { opacity: 0; transform: scale(2.4); filter: blur(6px); } }
        @keyframes filmCrossfade { from { opacity: 0; } to { opacity: 1; } }
        @keyframes filmPhotoIn { from { opacity: 0; transform: scale(1.06); } to { opacity: 1; transform: scale(1); } }
        @keyframes filmParaIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes filmParaOut { from { opacity: 1; } to { opacity: 0; } }
        /* zoom-settle + focus pull (letter-spacing reflowed multi-line text) */
        @keyframes filmTitleIn {
          0% { opacity: 0; transform: scale(1.14); filter: blur(10px); }
          60% { opacity: 1; filter: blur(2px); }
          100% { opacity: 1; transform: scale(1); filter: blur(0); }
        }
        @keyframes filmPush { from { transform: scale(1); } to { transform: scale(1.05); } }
        @keyframes filmDrift { from { transform: scale(1); } to { transform: scale(1.08); } }
        .film-sweep {
          -webkit-mask-image: linear-gradient(100deg, #000 35%, transparent 55%);
          mask-image: linear-gradient(100deg, #000 35%, transparent 55%);
          -webkit-mask-size: 300% 100%;
          mask-size: 300% 100%;
        }
        @keyframes filmSweepIn {
          0% { opacity: 1; -webkit-mask-position: 120% 0; mask-position: 120% 0; }
          100% { opacity: 1; -webkit-mask-position: 0% 0; mask-position: 0% 0; }
        }
        /* liquid pour: words fall in, stretched like a droplet, then settle */
        @keyframes filmWordIn {
          0% { opacity: 0; transform: translateY(-0.9em) scale(0.94, 1.28); filter: blur(10px); }
          45% { opacity: 1; filter: blur(3px); }
          75% { transform: translateY(0.07em) scale(1.03, 0.97); filter: blur(0.5px); }
          100% { opacity: 1; transform: none; filter: blur(0); }
        }
        .film-word { opacity: 0; display: inline-block; }
        /* the film clock owns every animation: paused = frozen frame */
        .film-paused * { animation-play-state: paused !important; }
      `}</style>

      {/* ── stage ── */}
      <div
        className={`absolute inset-0 ${paused ? "film-paused" : ""}`}
        onPointerDown={onStageDown}
        onPointerUp={onStageUp}
        onPointerCancel={onStageUp}
      >
        {scenes.map((sc, i) => {
          const on = i === idx || i === fading;
          const st = seekState[sc.id];
          return (
            <div
              key={`${sc.id}:${st?.k ?? 0}`}
              aria-hidden={i !== idx}
              className="absolute inset-0 transition-opacity duration-1000"
              style={{ opacity: i === idx ? 1 : 0, pointerEvents: i === idx ? "auto" : "none", zIndex: i === idx ? 2 : on ? 1 : 0 }}
            >
              <FilmCtx.Provider value={i === idx ? st?.off ?? 0 : 0}>{sc.render(on)}</FilmCtx.Provider>
            </div>
          );
        })}

        {/* persistent section titles — quiet documentary supers */}
        {(() => {
          const SUPERS: Record<string, { label: string; dark?: boolean }> = {
            familybody: { label: "Wild and Free Today. Alone Tomorrow." },
            promisebody: { label: "Saving Them Together, Not One at a Time." },
            graze: { label: "Room to Roam" },
            run: { label: "Room to Roam" },
            nap: { label: "Room to Roam" },
            storiesgrid: { label: "Every Burro, Every Family Has a Story", dark: true },
          };
          const sup = SUPERS[scenes[idx].id];
          if (!sup) return null;
          return (
            <div
              key={sup.label}
              className="absolute top-[118px] sm:top-[134px] left-6 sm:left-12 z-10 pointer-events-none"
              style={{ animation: "filmParaIn 0.8s ease 200ms both" }}
            >
              <p
                className={`text-[11px] sm:text-xs font-extrabold uppercase tracking-[0.28em] ${
                  sup.dark ? "text-charcoal/75" : "text-white/90 [text-shadow:0_1px_8px_rgba(0,0,0,0.6)]"
                }`}
              >
                {sup.label}
              </p>
              {/* cactus green over photos, sky on light scenes */}
              <span className={`block w-10 h-[3px] mt-1.5 rounded-full ${sup.dark ? "bg-sky" : "bg-[#6f9b67]"}`} />
            </div>
          );
        })()}
      </div>

      {/* ── top chrome: nav + transport ── */}
      <header className="absolute top-0 inset-x-0 z-20">
        <div className="bg-gradient-to-b from-black/55 to-transparent pb-6">
          <div className="max-w-6xl mx-auto px-4 sm:px-6 h-16 sm:h-20 flex items-center justify-between gap-4">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src="/DDlogo.png"
              alt="Donkey Dreams Sanctuary"
              className="h-14 sm:h-16 w-auto drop-shadow-[0_1px_6px_rgba(0,0,0,0.45)]"
            />
            <nav className="hidden md:flex items-center gap-5">
              {NAV.map((n) => (
                <Link key={n.label} href={n.href} className="text-sm font-semibold text-white/85 hover:text-white transition-colors">
                  {n.label}
                </Link>
              ))}
            </nav>
            <Link
              href="/donate"
              className="shrink-0 px-4 py-2 rounded-full bg-sky text-charcoal text-sm font-extrabold hover:bg-sky-light transition-colors"
            >
              Donate Now
            </Link>
          </div>
          {/* transport */}
          <div className="max-w-6xl mx-auto px-4 sm:px-6 flex items-center gap-3 mt-1">
            <button
              onClick={togglePlay}
              className="shrink-0 w-8 h-8 rounded-full bg-white/15 backdrop-blur text-white flex items-center justify-center hover:bg-white/30 transition-colors"
              aria-label={playing ? "Pause" : "Play"}
            >
              {playing ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4 ml-0.5" />}
            </button>
            <div
              className="relative flex-1 h-6 flex items-center cursor-pointer group touch-none"
              onPointerDown={(e) => {
                draggingRef.current = true;
                e.currentTarget.setPointerCapture(e.pointerId);
                seekTo(timeAt(e));
              }}
              onPointerMove={(e) => {
                const g = timeAt(e);
                const r = e.currentTarget.getBoundingClientRect();
                setHoverTip({ x: e.clientX - r.left, label: `${titleAt(g)} · ${fmt(g)}` });
                if (draggingRef.current) seekTo(g);
              }}
              onPointerUp={() => (draggingRef.current = false)}
              onPointerCancel={() => (draggingRef.current = false)}
              onPointerLeave={() => !draggingRef.current && setHoverTip(null)}
            >
              <div className="w-full h-[5px] group-hover:h-[8px] transition-all rounded-full bg-white/25 overflow-hidden">
                <div className="h-full bg-sky rounded-full" style={{ width: `${Math.min(100, (progress / total) * 100)}%` }} />
              </div>
              {/* playhead */}
              <span
                className="absolute top-1/2 -translate-y-1/2 -translate-x-1/2 w-3 h-3 rounded-full bg-white shadow opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"
                style={{ left: `${Math.min(100, (progress / total) * 100)}%` }}
              />
              {/* chapter ticks */}
              {starts.map((s, i) =>
                i > 0 && Number.isFinite(scenes[i - 1].dur) ? (
                  <span
                    key={i}
                    className="absolute top-1/2 -translate-y-1/2 w-[2px] h-[5px] bg-black/30 pointer-events-none"
                    style={{ left: `${(s / total) * 100}%` }}
                  />
                ) : null
              )}
              {hoverTip && (
                <span
                  className="absolute bottom-7 -translate-x-1/2 px-2 py-1 rounded bg-black/80 text-white text-[11px] font-semibold whitespace-nowrap pointer-events-none"
                  style={{ left: hoverTip.x }}
                >
                  {hoverTip.label}
                </span>
              )}
            </div>
            <span className="hidden sm:inline text-[11px] font-semibold text-white/80 tabular-nums">
              {fmt(progress)} / {fmt(total)}
            </span>
            <button
              onClick={soundOn ? disableSound : enableSound}
              className={`shrink-0 inline-flex items-center gap-1.5 px-3 h-8 rounded-full text-xs font-bold transition-colors ${
                soundOn ? "bg-sky text-charcoal" : "bg-white/15 backdrop-blur text-white hover:bg-white/30"
              }`}
            >
              {soundOn ? <Volume2 className="w-4 h-4" /> : <VolumeX className="w-4 h-4" />}
              <span className="hidden sm:inline">{soundOn ? "Narration on" : "Narration"}</span>
            </button>
          </div>
        </div>
      </header>

      {/* tap-for-sound chip (until armed) */}
      {!soundOn && idx < scenes.length - 1 && (
        <button
          onClick={enableSound}
          className="absolute bottom-6 left-1/2 -translate-x-1/2 z-20 inline-flex items-center gap-2 px-4 py-2.5 rounded-full bg-black/60 backdrop-blur text-white text-sm font-bold hover:bg-black/80 transition-colors"
        >
          <Volume2 className="w-4 h-4" />
          Tap for narration
        </button>
      )}
    </div>
  );
}
